  where not exists (select 1 from portal_products where name_en = 'TL Egg Tofu')
  returning id
), pid as (select id from p union all select id from portal_products where name_en = 'TL Egg Tofu' limit 1)
insert into portal_product_variants (item_code, product_id, label_en, label_ms, label_zh, website_slug, sort)
select x.item_code, pid.id, x.label_en, x.label_ms, x.label_zh, x.slug, x.sort
  from pid, (values ('TL120', '120g', '120g', '120g', 'tl-egg-tofu-120gm', 10), ('TL3X1', '3 × 120g', '3 × 120g', '3 × 120g', 'tl-egg-tofu-3-x-120gm', 20), ('TLS130', '130g', '130g', '130g', 'tl-egg-tofu-130gm', 30), ('TLS30P', 'Bag · 30 × 130g', 'Beg · 30 × 130g', '整袋 · 30 × 130g', null, 40), ('TLS180K', 'Carton · 180 × 130g', 'Karton · 180 × 130g', '整箱 · 180 × 130g', null, 50))
